def check_following(response):
    paragraphs = response.strip().split("\n\n")
    if len(paragraphs) != 3:
        return False
    for paragraph in paragraphs:
        sentences = re.split(r'(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=[.!?])\s', paragraph.strip())
        if len(sentences) > 2:
            return False
    return True

